const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  const ev = (obj) => new Promise((resolve, reject) => obj.evaluate((v, e) => e ? reject(e) : resolve(v)));
  const safeNum = (v) => (v === null || v === undefined || isNaN(v)) ? null : v;

  // 1. Geometry & Time Definitions
  const brazil = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Brazil'))
    .geometry();

  const yearA = 2003;
  const yearB = 2019;
  const scale = 1000; // per requirement (>=1000m)
  const maxPixels = 1e13;

  // 2. Data Acquisition & Check with fallback
  async function getYearImage(year) {
    const datasets = ['MODIS/061/MCD12Q1', 'MODIS/006/MCD12Q1'];
    for (const ds of datasets) {
      const col = ee.ImageCollection(ds)
        .filterDate(`${year}-01-01`, `${year}-12-31`)
        .filterBounds(brazil);
      const n = await ev(col.size());
      if (n > 0) {
        const img = ee.Image(col.first()).select('LC_Type1');
        return { ok: true, img, n, ds };
      }
    }
    return { ok: false };
  }

  let imgAInfo, imgBInfo;
  try {
    imgAInfo = await getYearImage(yearA);
    imgBInfo = await getYearImage(yearB);
  } catch (e) {
    console.log(`Error checking collections: ${e}`);
    console.log('D');
    return;
  }

  if (!imgAInfo.ok || !imgBInfo.ok) {
    console.log(`Images found: ${yearA}=${imgAInfo.ok ? imgAInfo.n : 0}, ${yearB}=${imgBInfo.ok ? imgBInfo.n : 0}`);
    console.log('C1');
    return;
  }

  // Brazil total area (km2)
  let brazilAreaKm2;
  try {
    const brArea = await ev(ee.Image.pixelArea().divide(1e6).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: brazil,
      scale: 3000,
      maxPixels: maxPixels
    }).get('area'));
    brazilAreaKm2 = safeNum(brArea);
  } catch (e) {
    console.log(`Error computing Brazil area: ${e}`);
    console.log('D');
    return;
  }
  if (brazilAreaKm2 === null) {
    console.log('Brazil area calculation failed.');
    console.log('C3');
    return;
  }

  // 3. Processing
  async function yearStats(info, year) {
    const lc = info.img;
    const cropland12 = lc.eq(12);
    const mosaic14 = lc.eq(14);
    const totalMask = cropland12.or(mosaic14);

    const areaImg = ee.Image.pixelArea().divide(1e6); // km2

    const reducers = {
      area12: areaImg.updateMask(cropland12).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: brazil,
        scale,
        maxPixels
      }).get('area'),
      area14: areaImg.updateMask(mosaic14).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: brazil,
        scale,
        maxPixels
      }).get('area'),
      areaTot: areaImg.updateMask(totalMask).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: brazil,
        scale,
        maxPixels
      }).get('area'),
      count12: ee.Image.constant(1).updateMask(cropland12).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: brazil,
        scale,
        maxPixels
      }).get('constant'),
      count14: ee.Image.constant(1).updateMask(mosaic14).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: brazil,
        scale,
        maxPixels
      }).get('constant'),
      countTot: ee.Image.constant(1).updateMask(totalMask).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: brazil,
        scale,
        maxPixels
      }).get('constant'),
    };

    try {
      const vals = await ev(ee.Dictionary(reducers));
      const out = {
        ds: info.ds,
        n: info.n,
        area12: safeNum(vals.area12),
        area14: safeNum(vals.area14),
        areaTot: safeNum(vals.areaTot),
        count12: safeNum(vals.count12),
        count14: safeNum(vals.count14),
        countTot: safeNum(vals.countTot)
      };
      return out;
    } catch (e) {
      return { error: e.toString() };
    }
  }

  const statsA = await yearStats(imgAInfo, yearA);
  const statsB = await yearStats(imgBInfo, yearB);

  // 4. Validation & Final Answer
  if (statsA.error || statsB.error) {
    console.log(`Computation error: ${statsA.error || ''} ${statsB.error || ''}`.trim());
    console.log('D');
    return;
  }
  if ([statsA.areaTot, statsB.areaTot].some(v => v === null)) {
    console.log('Calculation returned null/invalid value.');
    console.log('C3');
    return;
  }
  if ((statsA.countTot || 0) <= 0 || (statsB.countTot || 0) <= 0) {
    console.log(`Valid pixels after masking: ${yearA}=${statsA.countTot || 0}, ${yearB}=${statsB.countTot || 0}`);
    console.log('C2');
    return;
  }

  // 5. Evidence prints (<=20 lines)
  console.log(`Datasets: ${yearA}=${statsA.ds} (imgs=${statsA.n}), ${yearB}=${statsB.ds} (imgs=${statsB.n})`);
  console.log(`Brazil area (km2): ${brazilAreaKm2.toFixed(0)}`);
  console.log(`${yearA}: cropland_km2=${(statsA.area12||0).toFixed(0)}, mosaic_km2=${(statsA.area14||0).toFixed(0)}, total_km2=${(statsA.areaTot||0).toFixed(0)}, cropland_pix=${(statsA.count12||0)}, mosaic_pix=${(statsA.count14||0)}, total_pix=${(statsA.countTot||0)}, pct_BR=${(100*(statsA.areaTot||0)/brazilAreaKm2).toFixed(2)}%`);
  console.log(`${yearB}: cropland_km2=${(statsB.area12||0).toFixed(0)}, mosaic_km2=${(statsB.area14||0).toFixed(0)}, total_km2=${(statsB.areaTot||0).toFixed(0)}, cropland_pix=${(statsB.count12||0)}, mosaic_pix=${(statsB.count14||0)}, total_pix=${(statsB.countTot||0)}, pct_BR=${(100*(statsB.areaTot||0)/brazilAreaKm2).toFixed(2)}%`);

  const diffKm2 = statsB.areaTot - statsA.areaTot;
  const pctBRdiff = 100 * diffKm2 / brazilAreaKm2;
  const ratio = (statsA.areaTot > 0) ? (statsB.areaTot / statsA.areaTot) : null;

  if (ratio === null || !isFinite(ratio)) {
    console.log('C3');
    return;
  }

  console.log(`Δ total_km2=${diffKm2.toFixed(0)}, Δ%BR=${pctBRdiff.toFixed(3)}%, ratio=${ratio.toFixed(3)}`);

  // Decision: increase if 2019 > 2003
  const increased = diffKm2 > 0;
  console.log(increased ? 'A' : 'B');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
